def all_samples():
    out = []
    for name, group in (("akademik", ACADEMIC), ("blog", BLOG), ("kurumsal", CORPORATE),
                        ("kisisel", PERSONAL_AI), ("zor-negatif", HARD_NEGATIVES),
                        ("haber", NEWS)):
        for t in group:
            out.append({"text": " ".join(t.split()), "label": 1, "lang": "tr",
                        "source": "claude/" + name, "attack": "none"})
    return out


if __name__ == "__main__":
    import json, os
    rows = all_samples()
    path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                        "data", "ai_tr.jsonl")
    with open(path, "w", encoding="utf-8") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    import collections
    c = collections.Counter(r["source"] for r in rows)
    print("  -> ai_tr.jsonl (%d kayit)" % len(rows))
    for k, v in sorted(c.items()):
        print("     %-22s %d" % (k, v))
